    /*
     * Scenarios
     */

    @Test
    public void adminListsUserStoreConfiguration() {
        givenAdminCredentials();

        whenRequestIsPerformed(new MethodSpec("GET"), "/configurableComponents/configurations");

        thenRequestSucceeds();
        thenResponseContainsPid(USER_STORE_PID);
        thenResponseContainsAdminPasswordHash();
    }

    @Test
    public void nonAdminListDoesNotContainUserStore() {
        givenIdentityWithPermissions(CONFIG_ONLY_USER, CONFIG_ONLY_PASSWORD, "rest.configuration");

        whenRequestIsPerformed(new MethodSpec("GET"), "/configurableComponents/configurations");

        thenRequestSucceeds();
        thenResponseDoesNotContainPid(USER_STORE_PID);
        thenResponseContainsPid(OTHER_PID);
        thenResponseDoesNotContainAdminPasswordHash();
    }

    @Test
    public void nonAdminByPidDoesNotReturnUserStore() {
        givenIdentityWithPermissions(CONFIG_ONLY_USER, CONFIG_ONLY_PASSWORD, "rest.configuration");

        whenRequestIsPerformed(new MethodSpec("POST"), "/configurableComponents/configurations/byPid",
                "{\"pids\":[\"" + USER_STORE_PID + "\",\"" + OTHER_PID + "\"]}");

        thenRequestSucceeds();
        thenResponseDoesNotContainPid(USER_STORE_PID);
        thenResponseContainsPid(OTHER_PID);
        thenResponseDoesNotContainAdminPasswordHash();
    }

    @Test
    public void adminSnapshotContainsUserStore() {
        givenAdminCredentials();

        whenSnapshotIsRequested(givenLatestSnapshotId());

        thenRequestSucceeds();
        thenResponseContainsPid(USER_STORE_PID);
        thenResponseContainsAdminPasswordHash();
    }

    @Test
    public void nonAdminSnapshotDoesNotContainUserStore() {
        final long snapshotId = givenLatestSnapshotId();
        givenIdentityWithPermissions(CONFIG_ONLY_USER, CONFIG_ONLY_PASSWORD, "rest.configuration");

        whenSnapshotIsRequested(snapshotId);

        thenRequestSucceeds();
        thenResponseDoesNotContainPid(USER_STORE_PID);
        thenResponseContainsPid(OTHER_PID);
        thenResponseDoesNotContainAdminPasswordHash();
    }

    @Test
    public void nonAdminCannotUpdateUserStore() {
        givenIdentityWithPermissions(CONFIG_ONLY_USER, CONFIG_ONLY_PASSWORD, "rest.configuration");
        givenCurrentUserStoreConfiguration();

        whenRequestIsPerformed(new MethodSpec("PUT"), "/configurableComponents/configurations/_update",
                "{\"configs\":[{\"pid\":\"" + USER_STORE_PID
                        + "\",\"properties\":{\"users.config\":{\"type\":\"STRING\",\"value\":\"[]\"}}}],"
                        + "\"takeSnapshot\":false}");

        thenResponseCodeIs(403);
        thenUserStoreConfigurationIsUnchanged();
    }

    @Test
    public void adminCanUpdateUserStore() {
        givenAdminCredentials();
        givenCurrentUserStoreConfiguration();

        whenUserStoreIsUpdatedWithCurrentValue();

        thenRequestSucceeds();
        thenUserStoreConfigurationIsUnchanged();
    }

    @Test
    public void nonAdminCannotRollbackToLatestSnapshot() {
        givenIdentityWithPermissions(CONFIG_ONLY_USER, CONFIG_ONLY_PASSWORD, "rest.configuration");
        givenCurrentUserStoreConfiguration();

        whenRequestIsPerformed(new MethodSpec("POST", "EXEC"), "/snapshots/_rollback");

        thenResponseCodeIs(403);
        thenUserStoreConfigurationIsUnchanged();
    }

    @Test
    public void nonAdminCannotRollbackToSpecificSnapshot() {
        final long snapshotId = givenLatestSnapshotId();
        givenIdentityWithPermissions(CONFIG_ONLY_USER, CONFIG_ONLY_PASSWORD, "rest.configuration");
        givenCurrentUserStoreConfiguration();

        whenRequestIsPerformed(new MethodSpec("POST", "EXEC"), "/snapshots/byId/_rollback",
                "{\"id\":" + snapshotId + "}");

        thenResponseCodeIs(403);
        thenUserStoreConfigurationIsUnchanged();
    }

