    private String responseBody() {
        return expectResponse().body.orElseThrow(() -> new IllegalStateException("expected body"));
    }

    private List<String> responsePids() {
        final JsonObject root = Json.parse(responseBody()).asObject();
        final List<String> pids = new java.util.ArrayList<>();
        for (final JsonValue config : root.get("configs").asArray()) {
            pids.add(config.asObject().get("pid").asString());
        }
        return pids;
    }

    private static Object getUserStoreUsersConfig() {
        try {
            final ComponentConfiguration config = getConfigurationService().getComponentConfiguration(USER_STORE_PID);
            assertNotNull("user store configuration not found", config);
            return config.getConfigurationProperties().get("users.config");
        } catch (final Exception e) {
            fail("failed to retrieve user store configuration: " + e.getMessage());
            throw new IllegalStateException("unreachable");
        }
    }

    private static ConfigurationService getConfigurationService() throws Exception {
        return WireTestUtil
                .trackService(ConfigurationService.class,
                        Optional.of("(service.pid=org.eclipse.kura.configuration.ConfigurationService)"))
                .get(30, TimeUnit.SECONDS);
    }

    @SuppressWarnings("unchecked")
    private static <S extends Role> S getOrCreateRole(final UserAdmin userAdmin, final String name,
            final Class<S> classz) {
        final Role role = userAdmin.getRole(name);

        if (classz.isInstance(role)) {
            return (S) role;
        }

        final int type = classz == User.class ? Role.USER : Role.GROUP;
        return (S) userAdmin.createRole(name, type);
    }
